INSERT INTO `campaigns` (`id`,`title`,`slug`,`short_description`,`description`,`image`,`gallery`,`goal_amount`,`raised_amount`,`start_date`,`end_date`,`status`,`is_emergency`,`is_featured`,`sort_order`,`created_at`,`updated_at`) VALUES
(1,'URGENT: Winter Blanket & Shelter Extension','urgent-winter-blanket-shelter-extension-demo','As temperatures drop, our elderly cows and rescued calves need extra warmth. Help us fund high-quality blankets and a new weather-proof shed.','Our 30 elderly cows and 12 rescued calves are at risk this winter. We need to procure 50 high-quality woolen blankets and complete construction of a new 1,200 sq.ft. weather-proof shed before the temperature drops below 5°C.\n\nFunds raised will cover:\n- Woolen blankets (₹1.2L)\n- Shed construction (₹2.5L)\n- Heating lamps for sick calves (₹50K)\n- Extra fodder reserve (₹80K)\n\nEvery contribution counts. Help us protect our Gau Mata this winter.',NULL,NULL,500000,325000,'2026-04-10 00:00:00','2026-07-10 00:00:00','emergency',1,1,0,'2026-05-10 05:41:49','2026-05-10 05:41:49'),
(2,'New Cow Ambulance for Mathura Region','new-cow-ambulance-for-mathura-region-demo','A fully-equipped cow ambulance can save dozens of lives every month across Mathura and Vrindavan.','We are raising funds for a fully-equipped cow ambulance to respond to emergencies across Mathura district. The ambulance will include a hydraulic lift, oxygen cylinders, IV equipment, first-aid kits, and trained handlers.\n\nThe vehicle will operate 24/7 and respond to:\n- Highway cattle accidents\n- Abandoned cows in distress\n- Medical emergencies in remote villages\n- Disaster response (floods, etc.)',NULL,NULL,1200000,380000,'2026-04-19 00:00:00','2026-09-10 00:00:00','active',0,1,1,'2026-05-10 05:41:49','2026-05-10 05:41:49'),
(3,'Goshala Veterinary Clinic Expansion','goshala-veterinary-clinic-expansion-demo','We are doubling our on-site veterinary infrastructure with a fully-equipped surgery room and recovery wing.','Our existing vet clinic handles 15-20 cows per day. With expansion, we will be able to serve 50+ animals daily, including surgeries, X-rays, and emergency stabilisation.',NULL,NULL,800000,145000,'2026-04-26 00:00:00','2026-11-10 00:00:00','active',0,0,2,'2026-05-10 05:41:49','2026-05-10 05:41:49'),
(4,'Janmashtami Annadan 2026','janmashtami-annadan-2026-demo','Join us for the largest Annadan of the year — feeding 5,000+ devotees and 500+ cows on Janmashtami.','Annual Annadan event that brings together volunteers, devotees and trustees for a day-long celebration of feeding and seva.',NULL,NULL,350000,0,'2026-07-10 00:00:00','2026-08-10 00:00:00','upcoming',0,0,3,'2026-05-10 05:41:49','2026-05-10 05:41:49'),
(5,'Rescued: 50 Cows from Drought-Hit District','rescued-50-cows-from-drought-hit-district-demo','Mission completed — 50 cows from Bundelkhand are now safe in our Goshala.','Thanks to your generous support, we successfully rescued and rehabilitated 50 cows from a drought-hit district last summer. All cows are now healthy and integrated with our herd.',NULL,NULL,600000,612000,'2025-09-10 00:00:00','2025-12-10 00:00:00','completed',0,0,4,'2026-05-10 05:41:49','2026-05-10 05:41:49');

