(1,5,'Nandi (The Brave)','nandi-the-brave-demo','Indian Desi','7 years','male','White & Grey','2024-05-10 00:00:00','Rescued from a highway accident near Mathura. Sustained leg injuries that took 8 months to heal. Today, he is the proud leader of our herd.','Nandi loves jaggery, evening aarti, and walks with the morning volunteers.','cows/9Ja2sGrcp7fYd45QkvupVZqXMtHCQivEx7H9FHOF.jpg',NULL,3100,1,1,'active',0,'2026-05-10 05:41:49','2026-05-10 06:19:25'),
(2,2,'Gauri (The Gentle)','gauri-the-gentle-demo','Gir','5 years','female','Brown & White','2025-05-10 00:00:00','Found abandoned in a city dump in Agra. Severely undernourished. Now a healthy mother to twin calves born at our Goshala.','Gauri has a special love for oil-cakes (khali) and never misses morning aarti.',NULL,NULL,2500,1,1,'active',1,'2026-05-10 05:41:49','2026-05-10 05:41:49'),
(3,3,'Lakshmi','lakshmi-demo','Sahiwal','4 years','female','Reddish brown','2025-09-10 00:00:00','Rescued from a slaughterhouse-bound truck. Today, she is one of the calmest cows in the Goshala.',NULL,NULL,NULL,2100,1,1,'active',2,'2026-05-10 05:41:49','2026-05-10 05:41:49'),
(4,7,'Govinda','govinda-demo','Indian Desi','8 months','male','White',NULL,'Born at our Goshala to mother Gauri. Loves running with the volunteers.',NULL,NULL,NULL,1500,1,1,'active',3,'2026-05-10 05:41:49','2026-05-10 05:41:49'),
(5,2,'Radha','radha-demo','Gir','6 years','female',NULL,NULL,'Found injured near a temple in Vrindavan. Leg surgery successful — fully active now.',NULL,NULL,NULL,2500,1,0,'active',4,'2026-05-10 05:41:49','2026-05-10 05:41:49'),
(6,5,'Arjun','arjun-demo','Indian Desi','3 years','male',NULL,NULL,'Rescued from highway abandonment. Fully rehabilitated.',NULL,NULL,NULL,2100,1,0,'active',5,'2026-05-10 05:41:49','2026-05-10 05:41:49'),
(7,6,'Tulsi','tulsi-demo','Indian Desi','15 years','female',NULL,NULL,'Elderly mother brought to us when her former owners could no longer care for her. Lives a peaceful retired life.',NULL,NULL,NULL,1800,1,0,'active',6,'2026-05-10 05:41:49','2026-05-10 05:41:49'),
(8,7,'Kanha','kanha-demo','Indian Desi','5 months','male',NULL,NULL,'Newborn calf rescued with his mother from an unsafe shelter.',NULL,NULL,NULL,1500,1,0,'active',7,'2026-05-10 05:41:49','2026-05-10 05:41:49');

