(7,'Water & Borewell Seva','water-borewell-seva','💧',NULL,'Help us maintain clean drinking water through our solar pumps and borewell systems.','Help us maintain clean drinking water through our solar pumps and borewell systems.','[501,1100,2100,5100]',1100,1,0,6,'2026-05-10 05:41:49','2026-05-10 05:41:49'),
(8,'Cow Ambulance Fund','cow-ambulance-fund','🚑',NULL,'Support our 24/7 cow rescue ambulance covering Mathura and surrounding districts.','Support our 24/7 cow rescue ambulance covering Mathura and surrounding districts.','[1100,2100,5100,11000]',2100,1,0,7,'2026-05-10 05:41:49','2026-05-10 05:41:49'),
(9,'Gau Daan (Lifetime Sponsor)','gau-daan-lifetime-sponsor','🌟',NULL,'Premium spiritual offering — lifetime sponsorship for one cow with annual photo updates.','Premium spiritual offering — lifetime sponsorship for one cow with annual photo updates.','[21000,51000,101000,251000]',51000,1,0,8,'2026-05-10 05:41:49','2026-05-10 05:41:49');

