INSERT INTO `events` (`id`,`title`,`slug`,`type`,`short_description`,`description`,`image`,`gallery`,`starts_at`,`ends_at`,`venue`,`address`,`location_url`,`rsvp_enabled`,`capacity`,`status`,`is_featured`,`created_at`,`updated_at`) VALUES
(1,'Janmashtami Annadan & Gau Pujan 2026','janmashtami-annadan-gau-pujan-2026-demo','festival','Day-long celebration of Lord Krishna\'s birth — Annadan, cow pujan, bhajan and prasad distribution.','All-day celebration starting with morning aarti, followed by special Gau Pujan, bhajans, prasad distribution and an evening cultural programme.\n\nDevotees from across Bharat are invited. Free Annadan from 11am to 5pm.',NULL,NULL,'2026-06-24 06:00:00','2026-06-24 21:00:00','Gopal Seva Goshala, Vrindavan','Vrindavan, Mathura, Uttar Pradesh',NULL,0,5000,'upcoming',1,'2026-05-10 05:41:49','2026-05-10 05:41:49'),
(2,'Gopashtami — The Sacred Day of Cows','gopashtami-the-sacred-day-of-cows-demo','festival','Celebrate the day Lord Krishna was officially given charge of the cows. Special pujan and decoration of all our cows.','Gopashtami is when Lord Krishna was given the responsibility of the cows. We honour this day with full pujan, decoration of every cow, and a special bhog.',NULL,NULL,'2026-07-09 06:00:00','2026-07-09 20:00:00','Gopal Seva Goshala',NULL,NULL,0,1500,'upcoming',1,'2026-05-10 05:41:50','2026-05-10 05:41:50'),
(3,'Govardhan Puja & Annakut','govardhan-puja-annakut-demo','festival','Symbolic Govardhan Parvat made of 56 dishes (Annakut) offered with full ritual and bhajans.','Annual Govardhan Puja with cow worship, hill-shaped offerings of 56 dishes, and grand evening aarti.',NULL,NULL,'2026-08-08 07:00:00',NULL,'Gopal Seva Goshala',NULL,NULL,0,NULL,'upcoming',0,'2026-05-10 05:41:50','2026-05-10 05:41:50'),
(4,'Monthly Cow Health Camp','monthly-cow-health-camp-demo','seva','Free veterinary health camp for cows in the surrounding villages — vaccination, deworming, and treatment.','Held on the first Sunday of every month. Veterinary doctors and trained volunteers provide free vaccination and treatment to cows from nearby villages.',NULL,NULL,'2026-05-25 08:00:00',NULL,'Goshala Vet Clinic',NULL,NULL,0,NULL,'upcoming',0,'2026-05-10 05:41:50','2026-05-10 05:41:50');

