INSERT INTO `team_members` (`id`,`name`,`role`,`group`,`bio`,`photo`,`email`,`phone`,`social_links`,`is_published`,`sort_order`,`created_at`,`updated_at`) VALUES
(1,'Gopal Das ji Maharaj','Founder & Chairman','trustee','Visionary founder of the Trust. Spent 30+ years in Gau Seva and Vedic studies.',NULL,NULL,NULL,NULL,1,0,'2026-05-10 05:41:50','2026-05-10 05:41:50'),
(2,'Smt. Radha Devi','Trustee & Secretary','trustee','Oversees daily operations and financial transparency.',NULL,NULL,NULL,NULL,1,1,'2026-05-10 05:41:50','2026-05-10 05:41:50'),
(3,'Shri Mukund Sharma','Trustee','trustee','Manages community outreach and partnerships.',NULL,NULL,NULL,NULL,1,2,'2026-05-10 05:41:50','2026-05-10 05:41:50'),
(4,'Pt. Suresh Joshi','Trustee & Treasurer','trustee','Chartered Accountant. Audits all finances and ensures compliance.',NULL,NULL,NULL,NULL,1,3,'2026-05-10 05:41:50','2026-05-10 05:41:50'),
(5,'Dr. Ramesh Iyer','Chief Veterinarian','veterinarian','BVSc & AH. Leads our on-site veterinary clinic and emergency response.',NULL,NULL,NULL,NULL,1,4,'2026-05-10 05:41:50','2026-05-10 05:41:50'),
(6,'Dr. Priya Mehta','Veterinarian','veterinarian','Specialises in calf care and surgical procedures.',NULL,NULL,NULL,NULL,1,5,'2026-05-10 05:41:50','2026-05-10 05:41:50'),
(7,'Anjali Verma','Volunteer Coordinator','team','Coordinates 200+ active volunteers across districts.',NULL,NULL,NULL,NULL,1,6,'2026-05-10 05:41:50','2026-05-10 05:41:50'),
(8,'Rakesh Yadav','Goshala Operations Lead','team','Oversees feeding, cleaning, and shed maintenance schedules.',NULL,NULL,NULL,NULL,1,7,'2026-05-10 05:41:50','2026-05-10 05:41:50'),
(9,'Naveen Tiwari','Communications Lead','team','Manages our digital presence and donor communications.',NULL,NULL,NULL,NULL,1,8,'2026-05-10 05:41:50','2026-05-10 05:41:50');

-- ----------------------------
-- Table: testimonials
-- ----------------------------
DROP TABLE IF EXISTS `testimonials`;
CREATE TABLE `testimonials` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` VARCHAR(255) NOT NULL,
  `role` VARCHAR(255) NULL,
  `location` VARCHAR(255) NULL,
  `avatar` VARCHAR(255) NULL,
  `quote` TEXT NOT NULL,
  `rating` BIGINT NOT NULL DEFAULT '5',
  `is_published` TINYINT(1) NOT NULL DEFAULT '1',
  `is_featured` TINYINT(1) NOT NULL DEFAULT '0',
  `sort_order` BIGINT NOT NULL DEFAULT '0',
  `created_at` DATETIME NULL,
  `updated_at` DATETIME NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `testimonials` (`id`,`name`,`role`,`location`,`avatar`,`quote`,`rating`,`is_published`,`is_featured`,`sort_order`,`created_at`,`updated_at`) VALUES
(1,'Rajesh Khanna','Donor','Mumbai',NULL,'Seeing the dedication of the volunteers at Gopal Seva Samarpan Trust changed my perspective on charity. The transparency in how they use every rupee is commendable.',5,1,1,0,'2026-05-10 05:41:50','2026-05-10 05:41:50'),
(2,'Smt. Meera Devi','Devotee','Vrindavan',NULL,'The peace I felt during the Gau Aarti at this Goshala is unmatched. Truly a spiritual sanctuary.',5,1,1,1,'2026-05-10 05:41:50','2026-05-10 05:41:50'),
(3,'Dr. Ramesh Iyer','Veterinary Volunteer','Mathura',NULL,'I have volunteered at many goshalas, but the medical infrastructure here rivals professional veterinary clinics.',5,1,1,2,'2026-05-10 05:41:50','2026-05-10 05:41:50'),
(4,'Anita Sharma','Monthly Donor','Delhi',NULL,'I sponsor a cow named Tulsi every month. The trust shares photos and care updates without fail. Real, transparent seva.',5,1,0,3,'2026-05-10 05:41:50','2026-05-10 05:41:50'),
(5,'Pandit Mukund Joshi','Spiritual Advisor','Vrindavan',NULL,'A model goshala. Every cow looks healthy, every shelter is clean — exactly how seva should be.',5,1,0,4,'2026-05-10 05:41:50','2026-05-10 05:41:50'),
(6,'Suresh & Vidhi Patel','CSR Partner','Ahmedabad',NULL,'Our company has partnered with the Trust for 3 years. Their reporting and impact metrics are world-class.',5,1,0,5,'2026-05-10 05:41:50','2026-05-10 05:41:50');

